/// Resolve and stat the `chat-session-resources/<session_id>/<tool_call_id>`
/// spill entry relative to the hook stdin's `transcript_path`
/// (`.../GitHub.copilot-chat/transcripts/<session>.jsonl`). Returns `None`
/// (unmeasured, never a fabricated zero) when the root can't be derived or
/// no spill file is found.
///
/// The real on-disk entry directory is named `<tool_call_id>__vscode-<epoch>`
/// (an unpredictable timestamp suffix appended by VS Code), so this matches
/// by prefix rather than an exact join.
fn stat_spill_output_chars(
    transcript_path: &Path,
    session_id: &str,
    tool_call_id: &str,
) -> Option<u64> {
    let chat_root = transcript_path.parent()?.parent()?;
    let session_dir = chat_root
        .join("chat-session-resources")
        .join(session_id);
    let prefix = format!("{tool_call_id}__");
    let entry_dir = std::fs::read_dir(&session_dir)
        .ok()?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .find(|path| {
            path.file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| {
                    name == tool_call_id || name.starts_with(&prefix)
                })
        })?;
    let candidate = ["content.txt", "content.json"]
        .iter()
        .map(|name| entry_dir.join(name))
        .find(|path| path.is_file())?;
    let bytes = std::fs::read(&candidate).ok()?;
    Some(String::from_utf8_lossy(&bytes).chars().count() as u64)
}

